import{_ as t,o,c as n,ag as s}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Workspaces & Members","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workspaces.md","filePath":"guide/workspaces.md"}'),a={name:"guide/workspaces.md"};function r(i,e,d,l,h,c){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="workspaces-members" tabindex="-1">Workspaces &amp; Members <a class="header-anchor" href="#workspaces-members" aria-label="Permalink to &quot;Workspaces &amp; Members&quot;">​</a></h1><p>A <strong>workspace</strong> is the container everything else lives in. Every document, folder, datasource, and API key belongs to exactly one workspace, and the people in that workspace are the people who can reach them.</p><p>Sharing a <em>single</em> document with someone outside the workspace is a different thing — that&#39;s a share link, covered in <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>.</p><h2 id="your-first-workspace" tabindex="-1">Your First Workspace <a class="header-anchor" href="#your-first-workspace" aria-label="Permalink to &quot;Your First Workspace&quot;">​</a></h2><p>You don&#39;t have to create one. The first time you sign in, Wafflebase creates a workspace for you called <strong>&lt;your username&gt;&#39;s Workspace</strong> and makes you its owner.</p><p>To create another, use the workspace switcher at the top of the sidebar: it shows the workspace you&#39;re currently in, lists the others you belong to, and offers <strong>New workspace</strong>. Enter a name and click <strong>Create</strong> — you&#39;re the owner of the new one too.</p><p>The switcher is also how you move between workspaces. Each has its own URL, <code>/w/&lt;workspace&gt;</code>, and its own documents list, templates, datasources, and analytics.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>There are exactly two roles: <strong>Owner</strong> and <strong>Member</strong>. Whoever creates a workspace is its owner; everyone who joins by invite is a member unless the invite says otherwise.</p><table tabindex="0"><thead><tr><th>Action</th><th>Member</th><th>Owner</th></tr></thead><tbody><tr><td>Open, create, and edit any document in the workspace</td><td>Yes</td><td>Yes</td></tr><tr><td>Create folders, and rename them</td><td>Yes</td><td>Yes</td></tr><tr><td>Delete or move a folder</td><td>Only ones you created</td><td>Yes</td></tr><tr><td>Delete or move a document to another workspace</td><td>Only ones you created</td><td>Yes</td></tr><tr><td>Create a <strong>viewer</strong> share link</td><td>Yes</td><td>Yes</td></tr><tr><td>Create an <strong>editor</strong> share link</td><td>Only for documents you created</td><td>Yes</td></tr><tr><td>Revoke someone else&#39;s share link</td><td>No</td><td>Yes</td></tr><tr><td>Create, edit, delete, and query datasources</td><td>Yes</td><td>Yes</td></tr><tr><td>See the list of API keys</td><td>Yes, but only via the CLI or REST API</td><td>Yes</td></tr><tr><td>Create or revoke an API key</td><td>No</td><td>Yes</td></tr><tr><td>Invite people, and revoke invites</td><td>No</td><td>Yes</td></tr><tr><td>Remove a member</td><td>Only yourself</td><td>Yes</td></tr><tr><td>Rename the workspace or change its URL</td><td>No</td><td>Yes</td></tr><tr><td>Delete the workspace</td><td>No</td><td>Yes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Membership is the only permission on a document</p><p>There are no per-document permissions inside a workspace. Every member can open and edit every document in it — folders organize documents, they don&#39;t restrict them. If some content shouldn&#39;t be visible to everyone on the list, it belongs in a different workspace.</p></div><h3 id="what-only-ones-you-created-means" tabindex="-1">What &quot;only ones you created&quot; means <a class="header-anchor" href="#what-only-ones-you-created-means" aria-label="Permalink to &quot;What &quot;only ones you created&quot; means&quot;">​</a></h3><p>For a handful of administrative actions — deleting a document, moving it to another workspace, minting an <strong>editor</strong> share link, revoking a link someone else made — Wafflebase asks whether you are the document&#39;s <em>author</em> or the workspace&#39;s <em>owner</em>. A member who didn&#39;t create the document can still edit its content, but can&#39;t do those four things to it. The rule is enforced on the server, not just in the interface.</p><p>An owner is a manager of <strong>every</strong> document in the workspace, including documents created by people who have since left.</p><div class="warning custom-block"><p class="custom-block-title">Datasource credentials are shared</p><p>A datasource connection is stored on the workspace, not on the person who added it. Any member can run queries against its saved credentials, and — for <strong>database</strong> connections — can edit or delete the connection too. There is no owner-only tier for them. <strong>Lakehouse</strong> connections are shared on the same terms but cannot be edited or deleted at all: the app has no screen for it. See <a href="/docs/sheets/datasources.html#connections-are-shared-with-the-workspace">Connections are shared with the workspace</a>.</p></div><h2 id="workspace-settings" tabindex="-1">Workspace Settings <a class="header-anchor" href="#workspace-settings" aria-label="Permalink to &quot;Workspace Settings&quot;">​</a></h2><p><strong>Settings</strong> in the sidebar opens <code>/w/&lt;workspace&gt;/settings</code>. It&#39;s a single page of sections:</p><ul><li><strong>Workspace Name</strong> — the display name, visible to all members</li><li><strong>Workspace URL</strong> — the slug after <code>/w/</code>. Changing it updates all links, and the settings page reloads at the new address</li><li><strong>Members</strong> — everyone in the workspace, with their username, email, and role</li><li><strong>Invites</strong> — <em>owners only</em></li><li><strong>API Keys</strong> — <em>owners only</em></li><li><strong>Danger Zone</strong> — <em>owners only</em></li></ul><p>A member sees the first three sections and nothing below them.</p><div class="tip custom-block"><p class="custom-block-title">API keys are listed to members, but not on this page</p><p>The server lets any member <em>list</em> a workspace&#39;s API keys — creating and revoking are owner-only. The Settings page doesn&#39;t act on that: it hides the whole <strong>API Keys</strong> section from anyone who isn&#39;t an owner, so a member has to use the CLI (<code>wafflebase api-keys list</code>) or the REST API to see the list. There is nothing to find in Settings.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The Name and URL fields are visible to members, but saving them is an owner action — a member who edits one gets a &quot;Failed to update workspace&quot; message rather than a disabled field.</p></div><h2 id="invite-someone" tabindex="-1">Invite Someone <a class="header-anchor" href="#invite-someone" aria-label="Permalink to &quot;Invite Someone&quot;">​</a></h2><p>Only an owner can invite.</p><ol><li>Open <strong>Settings</strong> for the workspace</li><li>Under <strong>Invites</strong>, click <strong>Create Invite</strong></li><li>A row appears in the table. Use the copy icon to put the link on your clipboard</li><li>Send that link however you like</li></ol><p>The link looks like <code>https://&lt;your-site&gt;/invite/&lt;token&gt;</code>.</p><div class="warning custom-block"><p class="custom-block-title">Nothing is emailed, and the link isn&#39;t tied to a person</p><p>Wafflebase doesn&#39;t send invitation emails — copying the link and delivering it is the whole flow. The invite isn&#39;t bound to an email address either: <strong>anyone</strong> who is signed in and has the link can join the workspace with it, and it keeps working for more than one person until you revoke it. Treat an invite link like a password.</p></div><p>The <strong>Create Invite</strong> button always creates a <em>member</em> invite that never expires — which is why the <strong>Expires</strong> column reads <strong>Never</strong>. Invites with a different role or an expiry can be created through the REST API, but not from this screen.</p><p>Revoke an invite with the trash icon in its row. That stops the link working immediately; it does not remove anyone who has already joined with it.</p><h3 id="accepting-an-invite" tabindex="-1">Accepting an invite <a class="header-anchor" href="#accepting-an-invite" aria-label="Permalink to &quot;Accepting an invite&quot;">​</a></h3><p>Opening the link signs you in if you aren&#39;t already, then joins you to the workspace and drops you into its documents list — there&#39;s no confirmation step or accept button.</p><p>If you&#39;re already a member, the link just opens the workspace and changes nothing: an invite never changes an existing member&#39;s role.</p><p>When someone joins, the workspace&#39;s owners and the person who created the invite are notified. See <a href="/docs/guide/collaboration.html#notifications">Notifications</a>.</p><h2 id="remove-a-member" tabindex="-1">Remove a Member <a class="header-anchor" href="#remove-a-member" aria-label="Permalink to &quot;Remove a Member&quot;">​</a></h2><p>In <strong>Settings → Members</strong>, an owner gets a trash icon on every member&#39;s row. Clicking it removes them straight away — there is no confirmation dialog.</p><p>What happens to the person:</p><ul><li>They lose access to every document, folder, and datasource in the workspace</li><li>Any API keys they created for this workspace are revoked, permanently. Adding them back later does not reactivate the old keys</li><li>Their other workspaces are untouched</li></ul><p>What happens to their work:</p><ul><li><strong>Nothing is deleted.</strong> Every document they created stays in the workspace and keeps their name as its author</li><li>Because they&#39;re no longer a member, they can no longer open those documents</li><li>The workspace&#39;s owners remain managers of them, so nothing becomes stranded</li></ul><h3 id="leaving-a-workspace" tabindex="-1">Leaving a workspace <a class="header-anchor" href="#leaving-a-workspace" aria-label="Permalink to &quot;Leaving a workspace&quot;">​</a></h3><p>A member can remove their own row to leave. An <strong>owner cannot leave</strong> — the option isn&#39;t offered, and the server refuses it.</p><div class="warning custom-block"><p class="custom-block-title">Roles are fixed once someone joins</p><p>There is no way to promote a member to owner, demote an owner, or transfer ownership after the fact — no control in the interface and no API for it. Owners also can&#39;t be removed from the Members table: the trash icon never appears on an owner&#39;s row.</p><p>In practice this means the role someone joins with is the role they keep.</p></div><p>An owner who wants out has two routes, and neither is in the interface:</p><ul><li><strong>Another owner removes them.</strong> The server only refuses an owner&#39;s request to remove <em>themselves</em>; one owner removing a different owner is allowed. Since Settings never draws the trash icon on an owner&#39;s row, this means calling <code>DELETE /workspaces/:id/members/:userId</code> directly — and it needs a second owner to exist, which means the workspace was set up with an owner-role invite (also API-only, see above).</li><li><strong>Delete the workspace.</strong> The only route available to a sole owner.</li></ul><p>Decide who should be an owner before you invite them.</p><h2 id="delete-a-workspace" tabindex="-1">Delete a Workspace <a class="header-anchor" href="#delete-a-workspace" aria-label="Permalink to &quot;Delete a Workspace&quot;">​</a></h2><p>Under <strong>Danger Zone</strong>, <strong>Delete this workspace</strong> asks you to type the workspace&#39;s name to confirm. Deleting it permanently removes its documents, folders, datasources, invites, API keys, and membership list. There is no undo, and no trash to recover from.</p><p>You can&#39;t delete your last workspace — Wafflebase refuses if it&#39;s the only one you belong to.</p><h2 id="workspaces-documents-and-folders" tabindex="-1">Workspaces, Documents, and Folders <a class="header-anchor" href="#workspaces-documents-and-folders" aria-label="Permalink to &quot;Workspaces, Documents, and Folders&quot;">​</a></h2><ul><li>Every document is in exactly one workspace, always. There&#39;s no &quot;no workspace&quot; state</li><li>A document can be <strong>moved</strong> to another workspace, by someone who is a manager of it and a member of the destination</li><li><strong>Folders</strong> organize a workspace&#39;s documents into a tree. They&#39;re purely organizational: a folder grants and restricts nothing, and deleting one returns its documents to the workspace root rather than deleting them. See <a href="/docs/pdf/organizing-with-folders.html">Organizing with Folders</a></li><li><strong>Datasources</strong>, <strong>API keys</strong>, and <strong>analytics</strong> are scoped to one workspace and don&#39;t cross between them</li><li><strong>Templates</strong> are the exception, and the only one. A template is published <em>from</em> a workspace, but using it creates the new document in whichever workspace <strong>you</strong> pick — you need only be a member of the destination, not of the workspace that published it. That is how the public gallery works at all. The content is copied; nothing is shared afterwards. See <a href="/docs/guide/templates.html">Templates</a></li><li><strong>Comments and mentions</strong> stay inside the workspace too — only members can be mentioned or notified</li></ul><h2 id="good-to-know" tabindex="-1">Good to Know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to Know&quot;">​</a></h2><ul><li>Signing out of one workspace isn&#39;t a thing — you&#39;re signed into Wafflebase, and the switcher moves you between the workspaces you belong to</li><li>Someone reading a document through a share link is <strong>not</strong> a member. They have no sidebar, no workspace, and can&#39;t be mentioned or notified</li><li>Renaming a workspace&#39;s URL breaks links people have bookmarked to <code>/w/&lt;old-slug&gt;/…</code></li></ul>',51)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
